code:
class C:
    def __init__(self, v):
        self.v = v
a, b = C(1), C(2)
a.v = 10
print(a.v, b.v)

class C:
    def hello():
        return "hi"
C().hello()

class P:
    def __init__(self, name):
        name = name
p = P("ada")
print(hasattr(p, "name"))

class C:
    count = 0
    def __init__(self):
        self.count += 1
C(); C()
print(C.count)

class A:
    @classmethod
    def make(cls):
        return cls()
class B(A):
    pass
print(type(B.make()).__name__)

class C:
    def m(self):
        return 1
obj = C()
f = obj.m
print(f(), f.__self__ is obj)

class A:
    def __init__(self):
        self.__pin = 1
a = A()
print(hasattr(a, "__pin"), a._A__pin)

class T:
    @property
    def f(self):
        return 1
T().f = 5

class T:
    def __init__(self, v):
        self.v = v
    @property
    def v(self):
        return self.v
    @v.setter
    def v(self, value):
        self.v = value

class Base:
    def __init__(self):
        self.x = 1
class Sub(Base):
    def __init__(self):
        self.y = 2
print(Sub().x)

class A:
    def who(self): return "A"
class B(A):
    def who(self): return "B" + super().who()
class C(A):
    def who(self): return "C" + super().who()
class D(B, C):
    pass
print(D().who())

def f(x):
    return x * 2
print(f(3), f("ab"), f([1]))

class A:
    def f(self, x):
        return 1
    def f(self, x, y):
        return 2
print(A().f(5))

class P:
    def __init__(self, x):
        self.x = x
print(P(1) == P(1))

class P:
    def __init__(self, x):
        self.x = x
    def __eq__(self, o):
        return self.x == o.x
print({P(1)})
